+<script>
+// Store sections data for filtering
+let sectionsData = [];
+
+<?php if ($sections && $sections->num_rows > 0): 
+    mysqli_data_seek($sections, 0);
+    while($sec = $sections->fetch_assoc()): ?>
+sectionsData.push({
+    id: <?php echo $sec['id']; ?>,
+    name: '<?php echo htmlspecialchars(addslashes($sec['name'])); ?>',
+    department_id: <?php echo $sec['department_id'] ?? 'null'; ?>
+});
+<?php endwhile; endif; ?>
+
+// Load sections based on selected department
+function loadSections() {
+    let departmentId = document.getElementById('department_id').value;
+    let sectionSelect = document.getElementById('section_id');
+    
+    sectionSelect.innerHTML = '<option value="">-- Select Section --</option>';
+    
+    let filteredSections = sectionsData.filter(s => s.department_id == departmentId);
+    
+    filteredSections.forEach(section => {
+        let option = document.createElement('option');
+        option.value = section.id;
+        option.textContent = section.name;
+        sectionSelect.appendChild(option);
+    });
+}
+
+// Toggle user account fields
+document.getElementById('create_user_account')?.addEventListener('change', function() {
+    let userFields = document.getElementById('userAccountFields');
+    if (this.checked) {
+        userFields.style.display = 'block';
+        document.getElementById('username').required = true;
+        document.getElementById('password').required = true;
+        document.getElementById('user_role').required = true;
+    } else {
+        userFields.style.display = 'none';
+        document.getElementById('username').required = false;
+        document.getElementById('password').required = false;
+        document.getElementById('user_role').required = false;
+    }
+});
+
+// Open modal for adding employee
+function openEmployeeModal() {
+    document.getElementById('modalTitle').innerHTML = '<i class="fas fa-user-plus"></i> Add Employee';
+    document.getElementById('action').value = 'add';
+    document.getElementById('employee_id').value = '';
+    document.getElementById('employeeForm').reset();
+    document.getElementById('userAccountFields').style.display = 'none';
+    document.getElementById('create_user_account').checked = false;
+    document.getElementById('employeeModal').style.display = 'block';
+}
+
+// Close employee modal
+function closeEmployeeModal() {
+    document.getElementById('employeeModal').style.display = 'none';
+}
+
+// Edit employee
+function editEmployee(id) {
+    fetch('?get_employee=' + id)
+        .then(response => response.json())
+        .then(data => {
+            if (data.success) {
+                let emp = data.employee;
+                
+                document.getElementById('modalTitle').innerHTML = '<i class="fas fa-user-edit"></i> Edit Employee';
+                document.getElementById('action').value = 'edit';
+                document.getElementById('employee_id').value = emp.id;
+                document.getElementById('lastname').value = emp.lastname;
+                document.getElementById('firstname').value = emp.firstname;
+                document.getElementById('middlename').value = emp.middlename || '';
+                document.getElementById('email').value = emp.email || '';
+                document.getElementById('contact').value = emp.contact || '';
+                document.getElementById('department_id').value = emp.department_id || '';
+                document.getElementById('position').value = emp.position || '';
+                document.getElementById('date_hired').value = emp.date_hired || '';
+                document.getElementById('status').value = emp.status || 'Active';
+                
+                if (emp.user_role) {
+                    document.getElementById('user_role').value = emp.user_role || 'user';
+                }
+                if (emp.user_status) {
+                    document.getElementById('user_status').value = emp.user_status || 'active';
+                }
+                
+                loadSections();
+                
+                setTimeout(() => {
+                    document.getElementById('section_id').value = emp.section_id || '';
+                }, 100);
+                
+                // Hide user account creation section for edit (use separate user management)
+                document.getElementById('userAccountSection').style.display = 'none';
+                
+                document.getElementById('employeeModal').style.display = 'block';
+            } else {
+                alert('Error loading employee details');
+            }
+        })
+        .catch(error => {
+            console.error('Error:', error);
+            alert('Error loading employee details');
+        });
+}
+
